    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: linear-gradient(135deg, #0f0f1e 0%, #1a1a2e 100%);
    color: #e0e0e0;
    min-height: 100vh;
    padding: 20px;
}

.contact-form-container {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
}

.form-wrapper {
    width: 100%;
    max-width: 500px;
    background: #16213e;
    border-radius: 12px;
    padding: 40px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 8px;
    color: #ffffff;
}

.form-description {
    font-size: 14px;
    color: #a0a0a0;
    margin-bottom: 32px;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

label {
    font-size: 14px;
    font-weight: 500;
    color: #e0e0e0;
}

input {
    padding: 12px 14px;
    border: 2px solid #2a3f5f;
    border-radius: 6px;
    background: #0f1624;
    color: #e0e0e0;
    font-size: 16px;
    transition: all 0.2s ease;
    font-family: inherit;
}

input::placeholder {
    color: #606080;
}

input:focus {
    outline: none;
    border-color: #4a90e2;
    box-shadow: 0 0 0 3px rgba(74, 144, 226, 0.1);
    background: #151d2c;
}

input:hover:not(:focus) {
    border-color: #3a5080;
}

input[aria-invalid="true"] {
    border-color: #e74c3c;
}

input[aria-invalid="true"]:focus {
    box-shadow: 0 0 0 3px rgba(231, 76, 60, 0.1);
}

.helper-text {
    font-size: 13px;
    color: #808090;
    line-height: 1.4;
}

.submit-button {
    padding: 12px 24px;
    background: linear-gradient(135deg, #4a90e2 0%, #357abd 100%);
    color: #ffffff;
    border: none;
    border-radius: 6px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 8px;
    font-family: inherit;
}

.submit-button:hover {
    background: linear-gradient(135deg, #357abd 0%, #2a5aa0 100%);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(74, 144, 226, 0.3);
}

.submit-button:active {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(74, 144, 226, 0.2);
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(74, 144, 226, 0.2), 0 4px 12px rgba(74, 144, 226, 0.3);
}

.error-message {
    font-size: 13px;
    color: #e74c3c;
    margin-top: 4px;
    display: none;
}

.error-message.show {
    display: block;
}

.success-message {
    padding: 14px 16px;
    background: #0d5a3a;
    color: #4ade80;
    border-radius: 6px;
    font-size: 14px;
    display: none;
    border: 1px solid #16a34a;
    margin-top: 24px;
}

.success-message.show {
    display: block;
}

/* Accessibility: Forced colors mode */
@media (forced-colors: active) {
    input {
        border-color: ButtonBorder;
        background: Canvas;
        color: CanvasText;
    }

    input:focus {
        outline: 2px solid Highlight;
        outline-offset: 2px;
    }

    .submit-button {
        background: ButtonFace;
        color: ButtonText;
        border: 2px solid ButtonBorder;
    }

    .submit-button:focus {
        outline: 2px solid Highlight;
        outline-offset: 2px;
    }
}

/* Responsive design */
@media (max-width: 480px) {
    .form-wrapper {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .form-field {
        gap: 6px;
    }
}
